                        <p class="location">&#x1F4CD; Beijing | National Center</p>
                    </div>
                    <div class="hospital-card">
                        <span class="rank">#1 Neurology</span>
                        <h4>Shanghai Huashan Hospital</h4>
                        <p class="specialty">Neurology & Neurosurgery</p>
                        <p class="location">&#x1F4CD; Shanghai | Fudan University</p>
                    </div>
                    <div class="hospital-card">
                        <span class="rank">#1 Neurosurgery</span>
                        <h4>Beijing Tiantan Hospital</h4>
                        <p class="specialty">Brain Tumors, Cerebrovascular</p>
                        <p class="location">&#x1F4CD; Beijing | Deep Experience w/ Int'l Patients</p>
                    </div>
                    <div class="hospital-card">
                        <span class="rank">#1 Oncology</span>
                        <h4>Sun Yat-sen University Cancer Center</h4>
                        <p class="specialty">Cancer Diagnosis & Surgery</p>
                        <p class="location">&#x1F4CD; Guangzhou | Comprehensive Cancer Center</p>
                    </div>
                    <div class="hospital-card">
                        <span class="rank">#1 Cancer Hospital</span>
                        <h4>Cancer Hospital CAMS</h4>
                        <p class="specialty">Medical & Surgical Oncology</p>
                        <p class="location">&#x1F4CD; Beijing | National Cancer Center</p>
                    </div>
