# Read and display all not-covered URLs grouped by category
with open('/tmp/not_covered.txt') as f:
    urls = [u.strip() for u in f if u.strip()]

# Group by category
categories = {}
for url in urls:
    if '/blog/' in url and url.endswith('.html'):
        cat = 'blog'
    elif '/news/' in url and url.endswith('.html'):
        cat = 'news'
    elif '/course/' in url:
        cat = 'course'
    elif '/stories/' in url:
        cat = 'stories'
    elif '/treatments/' in url:
        cat = 'treatments'
    else:
        cat = 'main'

    if cat not in categories:
        categories[cat] = []
    categories[cat].append(url)

for cat, urls in sorted(categories.items()):
    print(f'\n=== {cat.upper()} ({len(urls)} URLs) ===')
    for u in urls:
        print(u)
